package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="lotes_inventario") public class LoteInventario { @Id @GeneratedValue private UUID id; @Column(name="empresa_id") private UUID empresaId; @ManyToOne @JoinColumn(name="sucursal_id") private Sucursal sucursal; @ManyToOne @JoinColumn(name="producto_id") private ProductoInventario producto; @Column(name="numero_lote") private String numeroLote; @Column(name="fecha_vencimiento") private LocalDate fechaVencimiento; private BigDecimal cantidad=BigDecimal.ZERO; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Sucursal getSucursal(){return sucursal;} public void setSucursal(Sucursal v){sucursal=v;} public ProductoInventario getProducto(){return producto;} public void setProducto(ProductoInventario v){producto=v;} public String getNumeroLote(){return numeroLote;} public void setNumeroLote(String v){numeroLote=v;} public LocalDate getFechaVencimiento(){return fechaVencimiento;} public void setFechaVencimiento(LocalDate v){fechaVencimiento=v;} public BigDecimal getCantidad(){return cantidad;} public void setCantidad(BigDecimal v){cantidad=v;} }
